const crypto = require('crypto');
const incoming = $json; const b = incoming.body ?? incoming;
const supplied = String(incoming.headers?.['x-webhook-secret'] ?? '');
if (!$env.LEAD_WEBHOOK_SECRET || supplied !== $env.LEAD_WEBHOOK_SECRET) throw new Error('unauthorized webhook');
const allowed = ['web','email','instagram','whatsapp','phone'];
const channel = String(b.channel ?? '').trim().toLowerCase();
const sourceEventId = String(b.sourceEventId ?? '').trim();
const email = String(b.email ?? '').trim().toLowerCase();
const phone = String(b.phone ?? '').replace(/[^+\d]/g, '');
const message = String(b.message ?? '').trim();
if (!allowed.includes(channel)) throw new Error('unsupported channel');
if (!sourceEventId) throw new Error('sourceEventId is required');
if (!email && !phone) throw new Error('email or phone is required');
if (!message) throw new Error('message is required');
const idempotencyKey = crypto.createHash('sha256').update(`${channel}:${sourceEventId}`).digest('hex');
return [{ json: { schemaVersion:'1.0', sourceEventId, channel, name:String(b.name??'').trim(), email, phone, message, consentToContact:b.consentToContact===true, serviceType:String(b.serviceType??'unknown').trim().toLowerCase()||'unknown', estimatedValue:Math.max(0, Number(b.estimatedValue)||0), urgency:['low','normal','high','emergency'].includes(b.urgency)?b.urgency:'normal', receivedAt:new Date(b.receivedAt??Date.now()).toISOString(), metadata:b.metadata??{}, idempotencyKey } }];

const lead = $('Normalize & Validate').item.json;
let score=10; const reasons=['valid inquiry'];
const up={low:0,normal:10,high:25,emergency:35}[lead.urgency]; score+=up; if(up) reasons.push(`urgency:${lead.urgency}`);
if(lead.estimatedValue>=5000){score+=25;reasons.push('estimated_value:high')} else if(lead.estimatedValue>=1000){score+=15;reasons.push('estimated_value:medium')} else if(lead.estimatedValue>0){score+=5;reasons.push('estimated_value:known')}
if(lead.serviceType!=='unknown'){score+=10;reasons.push('service_type:known')}
if(lead.phone&&lead.email){score+=10;reasons.push('contactability:two_channels')}
if(lead.consentToContact){score+=10;reasons.push('contact_consent:true')}
score=Math.min(100,score); const priority=score>=70?'high':score>=40?'medium':'low'; const slaMinutes=priority==='high'?15:priority==='medium'?60:240;
const humanHandoff=lead.urgency==='emergency'||score>=70;
return [{json:{...lead,score,priority,slaMinutes,reasons,humanHandoff,action:humanHandoff?'human_handoff':lead.consentToContact?'safe_followup':'await_consent'}}];
